import { useEffect, useRef } from 'react';
import runCrpvScripts from './runCrpvScripts.js';
import * as demoQuiz from './demoQuiz.js';
import * as demoWorkSkep from './demoWorkSkep.js';
import './crpv.css';
import './crpvFonts.css';

const DEMOS = { quiz: demoQuiz, workSkep: demoWorkSkep };

/**
 * One of the redesigned CRPV features tabs, mounted exactly as designed
 * (markup, CSS and scripts generated by scripts/build-crpv-embed.cjs).
 * demo="quiz"     → Conversion Quiz™
 * demo="workSkep" → Diagnostic Workshop + Skepticism Sequence
 *
 * The scripts only ever look inside this host element, and their cleanup
 * clears timers/listeners — so the pillar can close and reopen (and React
 * StrictMode can double-mount) without leaks. The markup is set in the
 * effect rather than rendered, so a React re-render can never wipe the live
 * DOM the scripts are holding on to.
 */
export default function CrpvEmbed({ demo }) {
  const hostRef = useRef(null);

  useEffect(() => {
    const host = hostRef.current;
    const { HTML, SCRIPTS } = DEMOS[demo];
    host.innerHTML = HTML;
    const cleanup = runCrpvScripts(host, SCRIPTS);
    return () => {
      cleanup();
      host.innerHTML = '';
    };
  }, [demo]);

  return <div ref={hostRef} className="crpv-scope" />;
}
